import { describe, it, expectTypeOf } from "vitest";
import { createStorage, prefixStorage } from "../src/index.ts";
import type { Storage, StorageValue } from "../src/index.ts";

describe("types", () => {
  it("default types for storage", async () => {
    const storage = createStorage();

    expectTypeOf(await storage.getItem("foo")).toEqualTypeOf<StorageValue | null>();

    expectTypeOf(await storage.getItem<boolean>("foo")).toEqualTypeOf<boolean | null>();

    expectTypeOf(await storage.getItem<{ hello: string }>("foo")).toEqualTypeOf<{
      hello: string;
    } | null>();

    await storage.setItem("foo", "str");
    await storage.set("bar", 1);
    await storage.removeItem("foo");
    await storage.remove("bar");
    await storage.del("baz");
  });

  it("indexed types for storage", async () => {
    const storage = createStorage<string>();

    expectTypeOf(await storage.getItem("foo")).toEqualTypeOf<string | null>();

    await storage.setItem("foo", "str");
    // @ts-expect-error should be a string
    await storage.set("bar", 1);

    await storage.removeItem("foo");
    await storage.remove("bar");
    await storage.del("baz");
  });

  it("namespaced types for storage", async () => {
    type TestObjType = {
      a: number;
      b: boolean;
    };
    type MyStorage = {
      items: {
        foo: string;
        bar: number;
        baz: TestObjType;
      };
    };
    const storage = createStorage<MyStorage>();

    expectTypeOf(await storage.getItem("foo")).toEqualTypeOf<string | null>();
    expectTypeOf(await storage.getItem("bar")).toEqualTypeOf<number | null>();
    expectTypeOf(await storage.getItem("unknown")).toEqualTypeOf<StorageValue | null>();
    expectTypeOf(await storage.get("baz")).toEqualTypeOf<TestObjType | null>();

    // @ts-expect-error
    await storage.setItem("foo", 1); // ts err: Argument of type 'number' is not assignable to parameter of type 'string'
    await storage.setItem("foo", "str");
    // @ts-expect-error
    await storage.set("bar", "str"); // ts err: Argument of type 'string' is not assignable to parameter of type 'number'.
    await storage.set("bar", 1);

    // should be able to get ts prompts: 'foo' | 'bar' | 'baz'
    await storage.removeItem("foo");
    await storage.remove("bar");
    await storage.del("baz");
  });

  it("prefix storage", () => {
    const storage1 = createStorage();
    const prefixedStorage1 = prefixStorage(storage1, "foo");
    expectTypeOf(prefixedStorage1).toEqualTypeOf<Storage<StorageValue>>();

    const storage2 = createStorage<string>();
    const prefixedStorage2 = prefixStorage(storage2, "foo");
    expectTypeOf(prefixedStorage2).toEqualTypeOf<Storage<string>>();

    const storage3 = createStorage<string>();
    const prefixedStorage3 = prefixStorage<number>(storage3, "foo");
    expectTypeOf(prefixedStorage3).toEqualTypeOf<Storage<number>>();
  });
});
import {
  createError,
  createRequiredError,
  type DriverFactory,
  importLib,
  type LibImport,
  type DriverDependencies,
} from "./utils/index.ts";
import type { GetKeysOptions } from "../types.ts";
import type {
  Store,
  BlobResponseType,
  // NOTE: this type is different in v10+ vs. pre-v10
  SetOptions,
  ListOptions,
  GetStoreOptions,
  GetDeployStoreOptions,
} from "@netlify/blobs";

export const DRIVER_DEPENDENCIES: DriverDependencies = {
  lib: {
    name: "@netlify/blobs",
    version: "^6.5.0 || ^7.0.0 || ^8.1.0 || ^9.0.0 || ^10.0.0 || ^11.0.0",
  },
};

const DRIVER_NAME = "netlify-blobs";

type GetOptions = { type?: BlobResponseType };

export type NetlifyStoreOptions =
  | NetlifyDeployStoreLegacyOptions
  | NetlifyDeployStoreOptions
  | NetlifyNamedStoreOptions;

export interface ExtraOptions {
  /** If set to `true`, the store is scoped to the deploy. This means that it is only available from that deploy, and will be deleted or rolled-back alongside it. */
  deployScoped?: boolean;

  /**
   * Optionally provide the [`@netlify/blobs`](https://www.npmjs.com/package/@netlify/blobs) library
   * to avoid dynamically importing it.
   */
  lib?: LibImport<typeof import("@netlify/blobs")>;
}

export interface NetlifyDeployStoreOptions extends GetDeployStoreOptions, ExtraOptions {
  name?: never;
  deployScoped: true;
}

export interface NetlifyDeployStoreLegacyOptions extends NetlifyDeployStoreOptions {
  // Added in v8.0.0. This ensures TS compatibility for older versions.
  region?: never;
}

export interface NetlifyNamedStoreOptions extends GetStoreOptions, ExtraOptions {
  name: string;
  deployScoped?: false;
}

const driver: DriverFactory<NetlifyStoreOptions, Promise<Store>> = (options) => {
  const { deployScoped, name, lib, ...opts } = options;
  let store: Promise<Store> | undefined;

  const getClient = () =>
    (store ??= (async () => {
      const { getStore, getDeployStore } = await importLib(DRIVER_NAME, "@netlify/blobs", lib);
      if (deployScoped) {
        if (name) {
          throw createError(DRIVER_NAME, "deploy-scoped stores cannot have a name");
        }
        return getDeployStore({ fetch, ...opts });
      }
      if (!name) {
        throw createRequiredError(DRIVER_NAME, "name");
      }
      // Ensures that reserved characters are encoded
      return getStore({ name: encodeURIComponent(name), fetch, ...opts });
    })());

  return {
    name: DRIVER_NAME,
    options,
    getInstance: getClient,
    async hasItem(key) {
      return (await getClient()).getMetadata(key).then(Boolean);
    },
    getItem: async (key, tops?: GetOptions) => {
      // @ts-expect-error has trouble with the overloaded types
      return (await getClient()).get(key, tops);
    },
    async getMeta(key) {
      return (await getClient()).getMetadata(key);
    },
    async getItemRaw(key, topts?: GetOptions) {
      // @ts-expect-error has trouble with the overloaded types
      return (await getClient()).get(key, { type: topts?.type ?? "arrayBuffer" });
    },
    async setItem(key, value, topts?: SetOptions) {
      // NOTE: this returns either Promise<void> (pre-v10) or Promise<WriteResult> (v10+)
      // TODO(serhalp): Allow drivers to return a value from `setItem`. The @netlify/blobs v10
      // functionality isn't usable without this.
      await (await getClient()).set(key, value, topts);
    },
    async setItemRaw(key, value: string | ArrayBuffer | Blob, topts?: SetOptions) {
      // NOTE: this returns either Promise<void> (pre-v10) or Promise<WriteResult> (v10+)
      // See TODO above.
      await (await getClient()).set(key, value, topts);
    },
    async removeItem(key) {
      return (await getClient()).delete(key);
    },
    async getKeys(base?: string, tops?: GetKeysOptions & Omit<ListOptions, "prefix" | "paginate">) {
      return (await (await getClient()).list({ ...tops, prefix: base })).blobs.map(
        (item) => item.key,
      );
    },
    async clear(base?: string) {
      const client = await getClient();
      return Promise.allSettled(
        (await client.list({ prefix: base })).blobs.map((item) => client.delete(item.key)),
      ).then(() => {});
    },
  };
};

export default driver;
